function positionDropdown(details) { if(!details.open) return; document.querySelectorAll('.evidence-picker[open]').forEach(other=>{ if(other!==details) other.open=false; }); const summary=details.querySelector('summary'); const menu=details.querySelector('.evidence-menu'); if(!summary || !menu) return; const rect=summary.getBoundingClientRect(); const width=Math.min(300,window.innerWidth-24); const left=Math.min(Math.max(12,rect.right-width),window.innerWidth-width-12); const menuHeight=Math.min(240,menu.scrollHeight || 240); const roomBelow=window.innerHeight-rect.bottom-12; const top=roomBelow >= Math.min(menuHeight,240) ? rect.bottom+6 : Math.max(12,rect.top-menuHeight-6); menu.style.left=`${left}px`; menu.style.top=`${top}px`; menu.style.width=`${width}px`; }
