function score() { const applicable = controls.filter(c => state.soa[c.ref]?.applicable); const points = applicable.reduce((n,c) => n + ({implemented: 1, partial: .5, open: 0, na: 0}[state.statuses[c.ref]] || 0) + (state.evidence.some(e => e.refs.includes(c.ref) && e.freshness !== 'expired') ? .25 : 0), 0); return Math.round(Math.min(100, points / (applicable.length * 1.25) * 100)); }
function statusLabel(s) { return ({implemented:'Implemented',partial:'Partial',open:'Not started',na:'Not applicable'})[s] || s; }
function badge(s) { const cls = s === 'implemented' || s === 'fresh' ? 'green' : s === 'partial' || s === 'expiring' ? 'amber' : s === 'open' || s === 'expired' ? 'red' : 'gray'; return `<span class="badge ${cls}">${s === 'fresh' ? 'Current' : s === 'expiring' ? 'Expiring soon' : s === 'expired' ? 'Expired' : statusLabel(s)}</span>`; }
function layout(content, title) { return `<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#"><span class="brand-mark"></span><span class="brand-name">asteria</span></a><div class="eyebrow">Information security</div><nav class="nav">${nav('dashboard','◒','Overview')}${nav('controls','⊙','ISO controls')}${nav('soa','▤','Statement of Applicability')}${nav('evidence','□','Evidence library')}${nav('policies','▤','ISMS / Policies')}${nav('procedures','≡','Procedures')}${nav('gaps','△','Gap assessment')}${nav('audits','◌','Internal audits')}${nav('actions','↗','Action plan')}${nav('roadmap','＋','Product roadmap')}</nav><div class="sidebar-footer"><div class="org-chip"><span class="avatar">NF</span><div><strong>Noor FinTech</strong><small>Riyadh · Demo workspace</small></div></div></div></aside><main class="main"><header class="topbar"><div><button class="mobile-menu" onclick="toggleMenu()">☰</button><span class="crumb">Workspace / <strong>${title}</strong></span></div><div class="top-actions"><button class="icon-btn" onclick="toast('Notifications are clear')">♧</button><div class="user-pill"><span class="avatar">MA</span><span>Mariam Al-Hadi</span><button class="logout" onclick="logout()">Sign out</button></div></div></header><section class="content">${content}</section></main></div>`; }
function nav(page, icon, label) { return `<button class="${state.page === page ? 'active' : ''}" onclick="navigate('${page}')"><span class="nav-icon">${icon}</span>${label}</button>`; }
function dashboard() { const sc = score(); const impl = Object.values(state.statuses).filter(s=>s==='implemented').length; const open = Object.values(state.statuses).filter(s=>s==='open').length; const expiring = state.evidence.filter(e=>e.freshness !== 'fresh').length; const themeRows = [['A5',37],['A6',8],['A7',14],['A8',34]].map(([theme,total]) => { const list=controls.filter(c=>c.theme===theme); const done=Math.round(list.reduce((n,c)=>n+(state.statuses[c.ref]==='implemented'?1:state.statuses[c.ref]==='partial'?.5:0),0)/list.length*100); return `<div class="theme-row"><div class="theme-name">${themes[theme]}<span>${total} controls</span></div><div class="bar"><i style="width:${done}%"></i></div><div class="percent">${done}%</div></div>` }).join(''); return layout(`<div class="page-head"><div><div class="eyebrow">Noor FinTech / ISMS readiness</div><h1>Certification, in view.</h1><p class="subhead">A clear line from each ISO 27001 control to its applicability decision and the evidence that proves it.</p></div><button class="button button-primary" onclick="navigate('controls')">Review controls &nbsp;→</button></div><div class="stats"><div class="card score-card" data-tour="overview-score"><div><div class="eyebrow">Certification readiness</div><div class="score-value">${sc}<span>/100</span></div><div class="stat-meta" style="color:#a4b4b5">Evidence coverage included</div></div><div class="ring"><b>${sc}%</b></div></div><div class="card stat-card"><div class="eyebrow">ISO 27001:2022</div><div class="stat-number">93</div><div class="stat-meta">Annex A controls in scope</div></div><div class="card stat-card"><div class="eyebrow">Control progress</div><div class="stat-number">${impl}</div><div class="stat-meta good">${impl} implemented · ${open} open</div></div><div class="card stat-card"><div class="eyebrow">Evidence watch</div><div class="stat-number">${expiring}</div><div class="stat-meta">Items need attention</div></div></div><div class="grid-2"><div class="card panel"><div class="panel-head"><div><h2>Annex A progress</h2><p>Implementation progress by control theme</p></div><button class="link" onclick="navigate('controls')">View all 93 →</button></div>${themeRows}</div><div class="card panel"><div class="panel-head"><div><h2>What needs attention</h2><p>Small actions that move readiness forward</p></div></div><div class="activity"><div class="activity-item"><span class="activity-dot"></span><p><strong>${open} controls</strong> still need an owner and implementation plan.</p><span class="activity-time">NOW</span></div><div class="activity-item"><span class="activity-dot" style="background:var(--gold);box-shadow:0 0 0 5px #fbf1dc"></span><p><strong>${expiring} evidence items</strong> are expiring or no longer current.</p><span class="activity-time">REVIEW</span></div><div class="activity-item"><span class="activity-dot" style="background:var(--coral);box-shadow:0 0 0 5px #fdebe6"></span><p><strong>${Object.values(state.soa).filter(x=>!x.applicable && !x.justification).length} SoA decisions</strong> need a written rationale.</p><span class="activity-time">OPEN</span></div></div></div></div><div class="callout"><div><h3>Keep your audit trail one step ahead.</h3><p>Complete your applicability decisions before collecting more evidence.</p></div><button class="button button-light" onclick="navigate('soa')">Open SoA builder →</button></div>`, 'Overview'); }
function crfControlsPage() { const list=state.crfControls.filter(c=>`${c.id} ${c.family} ${c.description}`.toLowerCase().includes(state.query.toLowerCase())); const rows=list.map(c=>`<tr><td><span class="control-ref">${c.id}</span></td><td><div class="control-title">${c.family}</div><div class="control-description">${c.description.replace(/\n/g,'<br>')}</div></td><td>${c.status==='Implemented'?'<span class="badge green">Implemented</span>':c.status==='Not Implemented'?'<span class="badge red">Not implemented</span>':'<span class="badge gray">'+(c.status || 'Not assessed')+'</span>'}</td><td>${c.risk ? riskBadge(c.risk) : '<span class="control-sub">Not rated</span>'}</td><td><button class="table-action" onclick="openCRFControl('${c.id}')">Read control →</button></td></tr>`).join(''); return layout(`<div class="page-head"><div><div class="eyebrow">CST CRF / Complete assessment catalogue</div><h1>Control catalogue</h1><p class="subhead">The full control universe from the assessment workbook. Every control begins at its source ID and keeps its required description, evidence expectation, findings, gap, risk, and recommended action.</p></div><button class="button button-primary" onclick="navigate('gaps')">Review identified gaps →</button></div><div class="control-switch"><button class="${state.controlSet==='iso'?'active':''}" onclick="state.controlSet='iso';state.query='';render()">ISO 27001 Annex A <span>93 controls</span></button><button class="${state.controlSet==='crf'?'active':''}" onclick="state.controlSet='crf';state.query='';render();loadCRFControls()">CST CRF Level 1–3 <span>215 controls</span></button></div><div class="card panel" data-tour="controls-table"><div class="table-toolbar"><div class="search"><input placeholder="Search ID, family, or full control description" value="${state.query}" oninput="state.query=this.value; render()" /></div><span class="catalogue-count">${state.crfControls.length ? `${list.length} of ${state.crfControls.length} controls` : 'Loading workbook controls…'}</span></div><div style="overflow:auto"><table><thead><tr><th style="width:105px">Control ID</th><th>Required control description</th><th>Status</th><th>Risk</th><th></th></tr></thead><tbody>${rows || '<tr><td colspan="5" class="empty-state">The workbook is loading or no controls match this search.</td></tr>'}</tbody></table></div></div>`, 'CST CRF controls'); }
function openCRFControl(id) { const c=state.crfControls.find(item=>item.id===id); if(!c) return; document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${c.id} / ${c.family}</div><h2 style="margin-top:7px">Assessment control</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="source-description"><label>Required control description</label><p>${c.description.replace(/\n/g,'<br>')}</p></div><div class="field"><label>Required evidence</label><textarea readonly>${c.evidence || 'No required evidence listed in the source workbook.'}</textarea></div>${c.findings ? `<div class="field"><label>Findings recorded</label><p class="report-text">${c.findings.replace(/\n/g,'<br>')}</p></div>` : ''}${c.gap ? `<div class="field"><label>Gap identified</label><p class="report-text">${c.gap.replace(/\n/g,'<br>')}</p></div>` : ''}${c.action ? `<div class="field"><label>Recommended action plan</label><p class="report-text">${c.action.replace(/\n/g,'<br>')}</p></div>` : ''}<div class="modal-actions"><button class="button button-primary" onclick="closeModal()">Close control</button></div></div></div></div>`); }
function controlsPage() { if(state.controlSet==='crf') return crfControlsPage(); const filtered=controls.filter(c=>(state.theme==='all'||c.theme===state.theme)&&(state.status==='all'||state.statuses[c.ref]===state.status)&&(`${c.ref} ${c.title}`.toLowerCase().includes(state.query.toLowerCase()))); const rows=filtered.map(c=>`<tr><td><span class="control-ref">${c.ref}</span></td><td><div class="control-title">${c.title}</div><div class="control-description">${c.description}</div><div class="control-sub">${themes[c.theme]} theme · Practical guidance synthesized from public ISO 27001 control references</div></td><td>${badge(state.statuses[c.ref])}</td><td>${evidencePicker(c.ref)}<div class="control-sub">${evidenceFor(c.ref).length} linked</div></td><td><button class="table-action" onclick="openControl('${c.ref}')">Inspect details →</button></td></tr>`).join(''); return layout(`<div class="page-head"><div><div class="eyebrow">ISO 27001:2022 / Annex A</div><h1>Control catalogue</h1><p class="subhead">The working inventory for your information security management system. Set a status, assign proof, and keep every decision reviewable.</p></div><button class="button button-primary" onclick="navigate('soa')">Build your SoA →</button></div><div class="control-switch"><button class="active" onclick="state.controlSet='iso';state.query='';render()">ISO 27001 Annex A <span>93 controls</span></button><button onclick="state.controlSet='crf';state.query='';render();loadCRFControls()">CST CRF Level 1–3 <span>215 controls</span></button></div><div class="card panel" data-tour="controls-table"><div class="table-toolbar"><div class="search"><input placeholder="Search controls by reference or name" value="${state.query}" oninput="state.query=this.value; render()" /></div><select class="select" onchange="state.theme=this.value;render()"><option value="all">All themes</option><option value="A5">Organizational</option><option value="A6">People</option><option value="A7">Physical</option><option value="A8">Technological</option></select><select class="select" onchange="state.status=this.value;render()"><option value="all">All statuses</option><option value="implemented">Implemented</option><option value="partial">Partial</option><option value="open">Not started</option><option value="na">Not applicable</option></select></div><div style="overflow:auto"><table><thead><tr><th style="width:90px">Ref</th><th>Control</th><th>Status</th><th>Linked evidence</th><th></th></tr></thead><tbody>${rows || '<tr><td colspan="5" class="empty-state">No controls match this view.</td></tr>'}</tbody></table></div></div>`, 'ISO controls'); }
function soaPage() { const missing=controls.filter(c=>!state.soa[c.ref]?.applicable && !state.soa[c.ref]?.justification).length; const rows=controls.map(c=>`<tr><td><span class="control-ref">${c.ref}</span></td><td><div class="control-title">${c.title}</div></td><td><label style="display:flex;align-items:center;gap:7px;font-size:11px"><input type="checkbox" ${state.soa[c.ref]?.applicable?'checked':''} onchange="setApplicable('${c.ref}',this.checked)" /> In scope</label></td><td><select class="select" style="height:32px;min-width:125px" onchange="setStatus('${c.ref}',this.value)"><option value="implemented" ${state.statuses[c.ref]==='implemented'?'selected':''}>Implemented</option><option value="partial" ${state.statuses[c.ref]==='partial'?'selected':''}>Partial</option><option value="open" ${state.statuses[c.ref]==='open'?'selected':''}>Not started</option><option value="na" ${state.statuses[c.ref]==='na'?'selected':''}>Not applicable</option></select></td><td><button class="table-action" onclick="openControl('${c.ref}')">${state.soa[c.ref]?.justification?'View rationale':'Add rationale'} →</button></td></tr>`).join(''); return layout(`<div class="page-head"><div><div class="eyebrow">Clause 6.1.3 / Applicability</div><h1>Statement of Applicability</h1><p class="subhead">Make the scope explicit. Every exclusion carries a rationale, and every included control can point back to its evidence.</p></div><button class="button button-primary" onclick="exportSoA()">Print / save PDF</button></div><div class="card panel" style="margin-bottom:17px"><div class="panel-head"><div><h2>SoA completion</h2><p>${missing ? `${missing} excluded decisions need a written rationale.` : 'All applicability decisions are documented.'}</p></div><strong style="font:22px var(--serif);color:var(--navy)">${Math.round(controls.filter(c=>state.soa[c.ref]?.applicable || state.soa[c.ref]?.justification).length/93*100)}%</strong></div><div class="progress-line"><i style="width:${Math.round(controls.filter(c=>state.soa[c.ref]?.applicable || state.soa[c.ref]?.justification).length/93*100)}%"></i></div></div><div class="card panel" data-tour="soa-table"><div style="overflow:auto"><table><thead><tr><th>Ref</th><th>Control</th><th>Applicability</th><th>Status</th><th>Rationale / detail</th></tr></thead><tbody>${rows}</tbody></table></div></div>`, 'Statement of Applicability'); }
function evidencePage() { const rows=state.evidence.map(e=>`<tr><td><div class="document-name"><span class="file-icon clickable-file" onclick="openDemoDocument('${e.name}','evidence')">${e.type}</span><div><div class="control-title clickable-title" onclick="openDemoDocument('${e.name}','evidence')">${e.name}</div><div class="control-sub">${e.owner} · collected ${e.date}</div></div></div></td><td>${evidenceAssignmentPicker(e)}<div class="control-sub">${e.refs.length} linked reference${e.refs.length===1?'':'s'}</div></td><td>${badge(e.freshness)}</td><td><button class="table-action" onclick="openDemoDocument('${e.name}','evidence')">View demo file →</button><button class="table-action" onclick="removeEvidence(${e.id})">Remove</button></td></tr>`).join(''); const expired=state.evidence.filter(e=>e.freshness==='expired').length; const current=state.evidence.filter(e=>e.freshness==='fresh').length; const linked=state.evidence.reduce((n,e)=>n+e.refs.length,0); return layout(`<div class="page-head"><div><div class="eyebrow">Proof / Linked evidence</div><h1>Evidence library</h1><p class="subhead">A controlled register for the proof behind your ISMS. Keep ownership, freshness, and control traceability in the same place.</p></div><button class="button button-primary" onclick="openUpload()">+ Add evidence</button></div>${assignmentSelector()}<div class="evidence-metrics"><div class="card evidence-metric"><span class="eyebrow">Total evidence</span><strong>${state.evidence.length}</strong><small>Registered items</small></div><div class="card evidence-metric"><span class="eyebrow">Current</span><strong class="metric-good">${current}</strong><small>Ready for review</small></div><div class="card evidence-metric"><span class="eyebrow">Needs attention</span><strong class="metric-alert">${expired}</strong><small>Expired or expiring</small></div><div class="card evidence-metric"><span class="eyebrow">Traceability</span><strong>${linked}</strong><small>Control links</small></div></div><div class="card panel evidence-register-panel" data-tour="evidence-register"><div class="panel-head"><div><h2>Evidence register</h2><p>Search and inspect supporting material, then assign it to one or more controls.</p></div><button class="link" onclick="exportEvidenceExcel()">Export register to Excel</button></div><div style="overflow:auto"><table><thead><tr><th>Evidence item</th><th>Linked controls</th><th>Freshness</th><th>Actions</th></tr></thead><tbody>${rows || '<tr><td colspan="4" class="empty-state">No evidence has been added yet.</td></tr>'}</tbody></table></div></div><div class="evidence-insight-grid"><div class="card panel"><div class="panel-head"><div><h2>Coverage signals</h2><p>What needs attention before an auditor samples the register</p></div></div><div class="activity"><div class="activity-item"><span class="activity-dot" style="background:var(--coral);box-shadow:0 0 0 5px #fdebe6"></span><p><strong>${expired} evidence item${expired===1?'':'s'} expired or expiring</strong><br><span class="control-sub">Renew the source and create a fresh version.</span></p></div><div class="activity-item"><span class="activity-dot" style="background:var(--gold);box-shadow:0 0 0 5px #fbf1dc"></span><p><strong>${controls.filter(c=>state.statuses[c.ref]==='implemented' && !state.evidence.some(e=>e.refs.includes(c.ref))).length} implemented controls lack proof</strong><br><span class="control-sub">Assign evidence from the control catalogue.</span></p></div></div></div><div class="card panel"><div class="panel-head"><div><h2>Evidence standard</h2><p>Every item should answer three questions</p></div></div><div class="evidence-standard"><div><b>1</b><span>What is it?</span><small>Name the policy, report, export, or record.</small></div><div><b>2</b><span>Who owns it?</span><small>Assign a responsible person or team.</small></div><div><b>3</b><span>What does it prove?</span><small>Link it to the exact control and page range.</small></div></div></div></div>`, 'Evidence library'); }
function documentsPage(kind) { const isPolicy=kind==='policy'; const docs=state.documents.filter(doc=>doc.kind===kind); const title=isPolicy?'ISMS / Policies':'Procedures'; const eyebrow=isPolicy?'ISMS / Controlled documents':'Operations / Controlled procedures'; const description=isPolicy?'The policy layer of the ISMS. Versioned, approved, and mapped to exact controls in either catalogue.':'The operating layer of the ISMS. Procedures show how policies are put into practice and provide another audit-ready evidence source.'; const rows=docs.map(doc=>`<tr><td><div class="document-name"><span class="file-icon clickable-file" onclick="openDemoDocument('${doc.name}','${kind}')">${isPolicy?'POL':'PROC'}</span><div><div class="control-title clickable-title" onclick="openDemoDocument('${doc.name}','${kind}')">${doc.name}</div><div class="control-sub">Version ${doc.version} · ${doc.owner}</div></div></div></td><td><span class="badge ${doc.status==='Approved'?'green':doc.status==='In review'?'amber':'gray'}">${doc.status}</span></td><td><div class="control-sub">${doc.review}</div><div style="margin-top:6px">${documentExpiry(doc)}</div></td><td>${documentPickerForPage(doc, kind)}</td><td><div class="row-actions"><button class="table-action" onclick="openDocumentUpdatePage('${doc.id}')">Update document</button><button class="table-action" onclick="openVersionHistory('${doc.id}')">History</button><button class="table-action" onclick="openDemoDocument('${doc.name}','${kind}')">View demo file →</button></div></td></tr>`).join(''); return layout(`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subhead">${description}</p></div><button class="button button-primary" onclick="openDocument('${kind}','')">+ Add ${isPolicy?'policy':'procedure'}</button></div>${assignmentSelector()}<div class="card panel"><div class="panel-head"><div><h2>${isPolicy?'Policy':'Procedure'} register</h2><p>${docs.length} controlled documents · version history and expiry are tracked</p></div><button class="link" onclick="exportDocumentsExcel('${kind}')">Export register to Excel</button></div><div style="overflow:auto"><table><thead><tr><th>Document</th><th>Status</th><th>Review and expiry</th><th>Linked controls</th><th>Lifecycle</th></tr></thead><tbody>${rows}</tbody></table></div></div>`, title); }
function openDocumentUpdatePage(id) { state.documentUpdateId=id; state.page='document-update'; render(); window.scrollTo(0,0); }
function documentUpdatePage() { const doc=state.documents.find(item=>item.id===state.documentUpdateId); if(!doc) return documentsPage('policy'); const kindLabel=doc.kind==='policy'?'Policy':'Procedure'; const suggested=nextVersion(doc.version); return layout(`<div class="page-head"><div><button class="back-link" onclick="navigate('${doc.kind==='policy'?'policies':'procedures'}')">← Back to ${kindLabel.toLowerCase()} register</button><div class="eyebrow" style="margin-top:22px">${kindLabel} lifecycle / Controlled update</div><h1>Update ${doc.name}</h1><p class="subhead">Create a new controlled version without losing the previous record. Upload the replacement document, explain the change, and set the next review point.</p></div><div class="document-state-card"><span>Current version</span><strong>v${doc.version}</strong><small>${documentExpiry(doc)}</small></div></div><div class="document-update-grid"><div class="card panel"><div class="panel-head"><div><h2>New version details</h2><p>The suggested version adds 1 to the current version.</p></div></div><div class="version-callout"><div><span>Current</span><strong>v${doc.version}</strong></div><div class="version-arrow">→</div><div><span>Suggested</span><strong>v${suggested}</strong></div></div><div class="field"><label>New version number</label><input id="page-update-version" value="${suggested}" /><div class="field-help">Suggestion: add 1 to the current version. Use a major version when the document structure or control intent changes significantly.</div></div><div class="field"><label>Upload new document</label><input id="page-update-file" type="file" accept=".pdf,.doc,.docx,.xlsx,.txt" /><div class="field-help">The demo stores the filename and lifecycle metadata. Full document viewing will be enabled in the production evidence repository.</div></div><div class="field"><label>What changed in this version? <span class="optional">Optional</span></label><textarea id="page-update-note" placeholder="Describe updated sections, new controls, approvals, or changes in operating practice."></textarea></div><div class="detail-grid"><div class="field"><label>Expiry date</label><input id="page-update-expiry" type="date" value="${doc.expiry || ''}" /></div><div class="field"><label>Status</label><select id="page-update-status"><option>Draft</option><option selected>In review</option><option>Approved</option></select></div></div><div class="modal-actions"><button class="button button-quiet" onclick="navigate('${doc.kind==='policy'?'policies':'procedures'}')">Cancel</button><button class="button button-primary" onclick="saveDocumentUpdatePage('${doc.id}')">Create version</button></div></div><div class="card panel"><div class="panel-head"><div><h2>Version history</h2><p>Previous versions remain available in the audit trail.</p></div></div><div class="version-list">${documentHistory(doc).slice().reverse().map((item,index)=>`<div class="version-row"><div class="version-number">v${item.version}</div><div><strong>${index===0?'Current version':'Previous version'}</strong><p>${item.note}</p><small>${item.date}</small></div></div>`).join('')}</div><div class="callout" style="display:block;margin-top:20px"><h3>Linked controls remain attached</h3><p>This update carries forward the document’s ${doc.refs.length} linked control${doc.refs.length===1?'':'s'} automatically.</p></div></div></div>`, `${kindLabel} update`); }
function saveDocumentUpdatePage(id) { const doc=state.documents.find(item=>item.id===id); if(!doc) return; const version=document.getElementById('page-update-version').value.trim(); if(!version) return toast('Enter a version number'); const file=document.getElementById('page-update-file').files[0]; const note=document.getElementById('page-update-note').value.trim() || 'Version updated without a change summary'; doc.history=documentHistory(doc); doc.history.push({version,date:'15 Aug 2026',note}); doc.version=version; doc.fileName=file?.name || doc.fileName || ''; doc.expiry=document.getElementById('page-update-expiry').value; doc.status=document.getElementById('page-update-status').value; save(); state.page=doc.kind==='policy'?'policies':'procedures'; render(); toast(`${doc.name} updated to version ${version}`); }
function exportRowsToExcel(rows, filename, sheetName) { if(typeof XLSX==='undefined') return toast('Excel export is unavailable'); const worksheet=XLSX.utils.json_to_sheet(rows); const workbook=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook,worksheet,sheetName); XLSX.writeFile(workbook,filename); toast(`${filename} downloaded`); }
function exportDocumentsExcel(kind) { const docs=state.documents.filter(doc=>doc.kind===kind); exportRowsToExcel(docs.map(doc=>({Document:doc.name,Type:kind==='policy'?'Policy':'Procedure',Version:doc.version,Owner:doc.owner,Status:doc.status,Expiry:doc.expiry || '',Review:doc.review,'Linked controls':doc.refs.join(', '),'File':doc.fileName || ''})),`${kind}-register.xlsx`,kind==='policy'?'Policies':'Procedures'); }
function exportEvidenceExcel() { exportRowsToExcel(state.evidence.map(e=>({Evidence:e.name,Type:e.type,Owner:e.owner,Collected:e.date,Freshness:e.freshness,'Linked controls':e.refs.join(', ')})),'evidence-register.xlsx','Evidence'); }
function exportGapsExcel() { exportRowsToExcel(state.gaps.map(g=>({'Control ID':g.id,Family:g.family,Description:g.description,Gap:g.gap,Risk:g.risk,Owner:g.owner,Due:g.due,Status:g.status,'Recommended action':g.action})),'gap-register.xlsx','Gaps'); }
function exportActionsExcel() { exportRowsToExcel(state.gaps.filter(g=>g.status!=='Closed').map(g=>({'Control ID':g.id,Family:g.family,Action:g.action,Owner:g.owner,Due:g.due,Risk:g.risk,Status:g.status})), 'action-plan.xlsx','Actions'); }
function documentPickerForPage(doc, kind) { const available=assignmentControls(); return `<details class="evidence-picker document-picker" ontoggle="positionDropdown(this)"><summary>${doc.refs.filter(ref=>available.some(c=>(state.assignmentSet==='crf'?c.id:c.ref)===ref)).length} linked <span>⌄</span></summary><div class="evidence-menu"><div class="field-help" style="padding:4px 8px 7px">Choose exact ${state.assignmentSet==='crf'?'CST CRF':'ISO 27001'} controls this ${kind} governs.</div><input class="assignment-search" type="search" placeholder="Search controls..." oninput="filterAssignmentMenu(this)" />${available.map(c=>{const ref=state.assignmentSet==='crf'?c.id:c.ref; return `<label><input type="checkbox" ${doc.refs.includes(ref)?'checked':''} onchange="toggleDocumentControl('${doc.id}','${ref}',this.checked)" /><span>${assignmentLabel(c)}<small>${state.assignmentSet==='crf'?'CST CRF control':themes[c.theme]}</small></span></label>`;}).join('')}</div></details>`; }
function toggleDocumentControl(docId, ref, checked) { const doc=state.documents.find(item=>item.id===docId); if(!doc) return; doc.refs=doc.refs.filter(item=>item!==ref); if(checked) doc.refs.push(ref); save(); render(); toast(`${doc.name} updated`); }
function openDocument(kind, ref='') { const isPolicy=kind==='policy'; document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${isPolicy?'ISMS policy':'Controlled procedure'} / New document</div><h2 style="margin-top:7px">Add ${isPolicy?'policy':'procedure'}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="field"><label>Name</label><input id="doc-name" placeholder="e.g. Cryptography Policy" /></div><div class="detail-grid"><div class="field"><label>Owner</label><input id="doc-owner" value="Mariam Al-Hadi" /></div><div class="field"><label>Version</label><input id="doc-version" value="1.0" /></div></div><div class="field"><label>Initial linked control</label><input id="doc-ref" value="${ref}" placeholder="e.g. A.8.24" /></div><div class="field"><label>Expiry date</label><input id="doc-expiry" type="date" /></div><div class="field"><label>Status</label><select id="doc-status"><option>Draft</option><option>In review</option><option>Approved</option></select></div><div class="modal-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveDocument('${kind}')">Add document</button></div></div></div></div>`); }
function nextVersion(version) { const parts=String(version || '1.0').split('.').map(Number); if(parts.some(Number.isNaN)) return `${version}.1`; parts[parts.length-1]+=1; return parts.join('.'); }
function openDocumentUpdate(id) { const doc=state.documents.find(item=>item.id===id); if(!doc) return; const suggested=nextVersion(doc.version); document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${doc.kind==='policy'?'ISMS policy':'Controlled procedure'} / Version update</div><h2 style="margin-top:7px">Update ${doc.name}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="version-callout"><div><span>Current version</span><strong>${doc.version}</strong></div><div class="version-arrow">→</div><div><span>Suggested next version</span><strong>${suggested}</strong></div></div><div class="field"><label>New version number</label><input id="update-version" value="${suggested}" /><div class="field-help">Suggested: add 1 to the current version. You can use a major or minor version if the change requires it.</div></div><div class="field"><label>What changed in this version? <span class="optional">Optional</span></label><textarea id="update-note" placeholder="Summarize the changes, updated sections, or reason for revision."></textarea></div><div class="field"><label>Expiry date</label><input id="update-expiry" type="date" value="${doc.expiry || ''}" /><div class="field-help">After this date the document is flagged for update.</div></div><div class="field"><label>New status</label><select id="update-status"><option>Draft</option><option selected>In review</option><option>Approved</option></select></div><div class="modal-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveDocumentUpdate('${id}')">Create version</button></div></div></div></div>`); }
function saveDocumentUpdate(id) { const doc=state.documents.find(item=>item.id===id); const version=document.getElementById('update-version').value.trim(); if(!version) return toast('Enter a version number'); const note=document.getElementById('update-note').value.trim() || 'Version updated without a change summary'; doc.history=documentHistory(doc); doc.history.push({version,date:'15 Aug 2026',note}); doc.version=version; doc.expiry=document.getElementById('update-expiry').value; doc.status=document.getElementById('update-status').value; save(); closeModal(); render(); toast(`${doc.name} updated to version ${version}`); }
function openVersionHistory(id) { const doc=state.documents.find(item=>item.id===id); if(!doc) return; const history=documentDocumentHistory(doc); document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${doc.kind==='policy'?'ISMS policy':'Controlled procedure'} / Version history</div><h2 style="margin-top:7px">${doc.name}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="version-list">${history.slice().reverse().map((item,index)=>`<div class="version-row"><div class="version-number">v${item.version}</div><div><strong>${index===0?'Current version':'Previous version'}</strong><p>${item.note}</p><small>${item.date}</small></div></div>`).join('')}</div><div class="modal-actions"><button class="button button-primary" onclick="closeModal()">Close history</button></div></div></div></div>`); }
function documentDocumentHistory(doc) { return documentHistory(doc); }
function saveDocument(kind) { const name=document.getElementById('doc-name').value.trim(); if(!name) return toast('Give the document a name first'); const validRefs=assignmentControls().map(c=>state.assignmentSet==='crf'?c.id:c.ref); const refs=document.getElementById('doc-ref').value.split(',').map(x=>x.trim()).filter(x=>validRefs.includes(x)); const version=document.getElementById('doc-version').value.trim()||'1.0'; state.documents.unshift({id:`${kind}-${Date.now()}`,kind,name,version,owner:document.getElementById('doc-owner').value.trim()||'Unassigned',status:document.getElementById('doc-status').value,review:'Review date to be set',expiry:document.getElementById('doc-expiry').value,refs,history:[{version,date:'15 Aug 2026',note:'Initial demo version'}]}); save(); closeModal(); render(); toast(`${kind==='policy'?'Policy':'Procedure'} added to the register`); }
function riskBadge(risk) { return `<span class="badge ${risk === 'High' ? 'red' : risk === 'Medium' ? 'amber' : 'green'}">${risk} risk</span>`; }
function gapsPage() { const open=state.gaps.filter(g=>g.status!=='Closed').length; const high=state.gaps.filter(g=>g.risk==='High' && g.status!=='Closed').length; const rows=state.gaps.map(g=>`<tr><td><span class="control-ref">${g.id}</span></td><td><div class="control-title">${g.family}</div><div class="control-sub">${g.description}</div></td><td>${riskBadge(g.risk)}</td><td>${g.status === 'Closed' ? '<span class="badge green">Closed</span>' : g.status === 'In progress' ? '<span class="badge amber">In progress</span>' : '<span class="badge red">Open</span>'}</td><td><button class="table-action" onclick="openGap('${g.id}')">Review gap →</button></td></tr>`).join(''); return layout(`<div class="page-head"><div><div class="eyebrow">Assessment / Imported CST CRF report</div><h1>Gap assessment</h1><p class="subhead">Turn assessment observations into owned work. The report’s gaps, risk ratings, and recommended actions are now a living register instead of a spreadsheet snapshot.</p></div><button class="button button-primary" onclick="navigate('actions')">Open action plan →</button></div><div class="stats"><div class="card stat-card"><div class="eyebrow">Open gaps</div><div class="stat-number">${open}</div><div class="stat-meta">Across the imported assessment</div></div><div class="card stat-card"><div class="eyebrow">High risk</div><div class="stat-number">${high}</div><div class="stat-meta">Need management attention</div></div><div class="card stat-card"><div class="eyebrow">In progress</div><div class="stat-number">${state.gaps.filter(g=>g.status==='In progress').length}</div><div class="stat-meta good">Actions already underway</div></div><div class="card stat-card"><div class="eyebrow">Source</div><div class="stat-number" style="font-size:22px">CST CRF</div><div class="stat-meta">Level 1–3 assessment report</div></div></div><div class="card panel"><div class="panel-head"><div><h2>Identified gaps</h2><p>Imported from the CRF CST 2026 assessment and normalized for action tracking.</p></div><button class="link" onclick="toast('Gap register export prepared')">Export register</button></div><div style="overflow:auto"><table><thead><tr><th>Control</th><th>Requirement and gap</th><th>Risk</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>`, 'Gap assessment'); }
function auditsPage() { const audit=state.audits[0]; return layout(`<div class="page-head"><div><div class="eyebrow">Assurance / Internal audit program</div><h1>Internal audits</h1><p class="subhead">Plan the audit, walk the controls, record findings, and send every issue into the action plan without re-keying the result.</p></div><button class="button button-primary" onclick="startAudit()">${audit.status === 'In progress' ? 'Continue audit' : 'Start audit'}</button></div><div class="grid-2"><div class="card panel"><div class="panel-head"><div><h2>Audit schedule</h2><p>Independent review calendar for the ISMS</p></div><button class="link" onclick="toast('New audit workflow will open here')">+ Schedule</button></div>${state.audits.map(a=>`<div class="audit-row"><div class="audit-mark">${a.status === 'In progress' ? '●' : '○'}</div><div><h3>${a.name}</h3><p>${a.scope}</p><div class="control-sub">Lead: ${a.lead} · ${a.date}</div><div class="progress-line"><i style="width:${a.progress}%"></i></div></div><span class="badge ${a.status === 'In progress' ? 'amber' : 'gray'}">${a.status}</span></div>`).join('')}</div><div class="card panel"><div class="panel-head"><div><h2>Audit checklist</h2><p>Current readiness review</p></div><strong style="font:22px var(--serif);color:var(--navy)">${audit.progress}%</strong></div><div class="audit-check"><label><input type="checkbox" checked onchange="toast('Scope confirmed')" /> Confirm ISMS scope and interested parties</label><label><input type="checkbox" checked onchange="toast('Control sample confirmed')" /> Sample Annex A controls and SoA decisions</label><label><input type="checkbox" onchange="toast('Evidence request added')" /> Test evidence freshness and traceability</label><label><input type="checkbox" onchange="toast('Findings review added')" /> Review open gaps and corrective actions</label></div><div class="callout" style="display:block"><h3>Audit outcome</h3><p>Findings raised here can become accountable actions with owners, due dates, and closure evidence.</p></div></div></div>`, 'Internal audits'); }
function actionsPage() { const active=state.gaps.filter(g=>g.status!=='Closed'); return layout(`<div class="page-head"><div><div class="eyebrow">Remediation / Corrective action plan</div><h1>Action plan</h1><p class="subhead">One accountable list for closing the gaps identified in your assessment. Owners, dates, risk, and closure evidence stay together.</p></div><button class="button button-primary" onclick="navigate('gaps')">Review gap register →</button></div><div class="card panel"><div class="panel-head"><div><h2>Remediation actions</h2><p>${active.length} active actions · sorted by risk and due date</p></div><button class="link" onclick="toast('Action plan export prepared')">Export plan</button></div><div style="overflow:auto"><table><thead><tr><th>Gap</th><th>Recommended action</th><th>Owner</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${active.map(g=>`<tr><td><span class="control-ref">${g.id}</span><div class="control-sub">${g.family}<br>${riskBadge(g.risk)}</div></td><td><div class="control-title">${g.action}</div><div class="control-sub">${g.gap}</div></td><td>${g.owner}</td><td><span class="control-sub">${g.due}</span></td><td><select class="select action-status" onchange="updateGapStatus('${g.id}',this.value)"><option ${g.status==='Open'?'selected':''}>Open</option><option ${g.status==='In progress'?'selected':''}>In progress</option><option>Closed</option></select></td><td><button class="table-action" onclick="openGap('${g.id}')">Edit →</button></td></tr>`).join('')}</tbody></table></div></div>`, 'Action plan'); }
function openGap(id) { const g=state.gaps.find(item=>item.id===id); document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${g.id} / ${g.family}</div><h2 style="margin-top:7px">Close the gap with evidence</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="gap-summary"><label>Requirement</label><p>${g.description}</p><label>Gap identified</label><p>${g.gap}</p></div><div class="field"><label>Recommended action</label><textarea id="gap-action">${g.action}</textarea></div><div class="detail-grid"><div class="field"><label>Owner</label><input id="gap-owner" value="${g.owner}" /></div><div class="field"><label>Due date</label><input id="gap-due" value="${g.due}" /></div></div><div class="field"><label>Status</label><select id="gap-status"><option ${g.status==='Open'?'selected':''}>Open</option><option ${g.status==='In progress'?'selected':''}>In progress</option><option ${g.status==='Closed'?'selected':''}>Closed</option></select></div><div class="field"><label>Closure evidence</label><select id="gap-evidence" class="select evidence-modal-select" multiple size="3">${evidenceOptions(g.id)}</select><div class="field-help">Link evidence that proves this action is complete. Upload new proof from Evidence Library.</div></div><div class="modal-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveGap('${g.id}')">Save action</button></div></div></div></div>`); }
function saveGap(id) { const g=state.gaps.find(item=>item.id===id); g.action=document.getElementById('gap-action').value.trim(); g.owner=document.getElementById('gap-owner').value.trim(); g.due=document.getElementById('gap-due').value.trim(); g.status=document.getElementById('gap-status').value; const selected=Array.from(document.getElementById('gap-evidence').selectedOptions).map(option=>Number(option.value)); state.evidence.forEach(e=>{ e.refs=e.refs.filter(ref=>ref!==id); if(selected.includes(e.id)) e.refs.push(id); }); save(); closeModal(); render(); toast(`Action ${id} saved`); }
function updateGapStatus(id,status) { const g=state.gaps.find(item=>item.id===id); g.status=status; save(); render(); toast(`Gap ${id} marked ${status.toLowerCase()}`); }
function startAudit() { state.audits[0].status='In progress'; state.audits[0].progress=Math.max(state.audits[0].progress,62); save(); render(); toast('Internal audit workspace opened'); }
function roadmapPage() { return layout(`<div class="page-head"><div><div class="eyebrow">Asteria / Product direction</div><h1>Beyond certification.</h1><p class="subhead">The first release makes ISO readiness visible. The product grows into the operating system for information security.</p></div></div><div class="grid-2"><div class="card roadmap-card"><div class="roadmap-item"><span class="roadmap-num">01</span><div><h3>ISO compliance core <span class="badge green">In this demo</span></h3><p>Controls, SoA, evidence, readiness signals, and audit-ready exports in one connected workspace.</p></div></div><div class="roadmap-item"><span class="roadmap-num">02</span><div><h3>Risk assessment workspace</h3><p>Asset inventory, inherent and residual risk, treatment plans, and a configurable risk methodology.</p></div></div><div class="roadmap-item"><span class="roadmap-num">03</span><div><h3>Enterprise integrations</h3><p>Entra ID, Intune, Jira, ServiceNow, cloud security platforms and SIEM evidence feeds.</p></div></div><div class="roadmap-item"><span class="roadmap-num">04</span><div><h3>Regional control packs</h3><p>Arabic RTL, NCA ECC, SAMA and GCC-ready deployment options for regulated organizations.</p></div></div></div><div class="card panel"><div class="eyebrow">Built for the region</div><h2 style="font:26px var(--serif);margin:12px 0">Your data. Your evidence. Your audit story.</h2><p class="subhead">Asteria will support regional cloud residency and client-hosted deployments, so security teams can choose the operating model that fits their obligations.</p><div class="callout" style="display:block;margin-top:25px"><h3>Partner preview workspace</h3><p>Use this flow to demonstrate the connection between a control decision and its proof.</p></div></div></div>`, 'Product roadmap'); }
function loginPage(error = '') { return `<div class="login-shell"><div class="login-aside"><a class="brand" href="#"><span class="brand-mark"></span><span class="brand-name">asteria</span></a><div class="login-quote"><div class="eyebrow">Information security, in view.</div><h1>Build an ISMS<br>people can trust.</h1><p>Asteria connects every ISO 27001 decision to the evidence and ownership behind it.</p></div><div class="login-foot">Private partner preview · Noor FinTech workspace</div></div><main class="login-main"><div class="login-card"><div class="eyebrow">Partner preview</div><h2>Sign in to Asteria</h2><p class="login-copy">Enter the demo credentials to open the Noor FinTech workspace.</p><form onsubmit="login(event)"><div class="field"><label for="login-email">Email</label><input id="login-email" type="email" autocomplete="username" placeholder="you@company.com" required /></div><div class="field"><label for="login-password">Password</label><input id="login-password" type="password" autocomplete="current-password" placeholder="Enter demo password" required /></div>${error ? `<div class="login-error">${error}</div>` : ''}<button class="button button-primary login-button" type="submit">Continue to workspace <span>→</span></button></form><div class="demo-credentials"><div class="eyebrow">Demo credentials</div><strong>demo@asteria.local</strong><span>NoorFinTech2026!</span></div></div><div class="login-legal">This is a product demonstration. Do not use these credentials for real systems.</div></main></div>`; }
function login(event) { event.preventDefault(); const email=document.getElementById('login-email').value.trim().toLowerCase(); const password=document.getElementById('login-password').value; if(email !== 'demo@asteria.local' || password !== 'NoorFinTech2026!') { document.getElementById('app').innerHTML=loginPage('The demo email or password is not correct.'); return; } state.authenticated=true; state.tourComplete=false; state.tourStep=0; sessionStorage.setItem('asteria-demo-auth','1'); sessionStorage.removeItem('asteria-tour-complete'); render(); }
function logout() { sessionStorage.removeItem('asteria-demo-auth'); sessionStorage.removeItem('asteria-tour-complete'); state.authenticated=false; state.tourComplete=false; state.tourStep=0; render(); }
const tourSteps = [
  { page:'dashboard', target:'overview-score', kicker:'01 / START HERE', title:'Check readiness first', text:'The user flow begins with the readiness pulse. It shows what is implemented, what has proof, and where the next useful action is.' },
  { page:'controls', target:'controls-table', kicker:'02 / CONTROL', title:'Choose a control to work on', text:'Open the catalogue, search for a requirement, inspect its practical intent, then connect the people, documents, and evidence responsible for it.' },
  { page:'soa', target:'soa-table', kicker:'03 / SCOPE', title:'Make the SoA decision', text:'For each control, confirm whether it is in scope and record the rationale. This creates the formal applicability story for the ISMS.' },
  { page:'evidence', target:'evidence-register', kicker:'04 / PROVE', title:'Attach evidence and keep it current', text:'Link proof to the control, record page-level traceability, and update evidence when it expires or a new version is issued.' },
  { page:'policies', target:'document-register', kicker:'05 / OPERATE', title:'Connect the operating documents', text:'Policies and procedures explain how controls work in the organization. Link controlled versions to the exact requirements they govern.' },
  { page:'gaps', target:'gap-register', kicker:'06 / IMPROVE', title:'Turn gaps into actions', text:'Assessment gaps become owned actions with risk, due dates, closure evidence, and a clear path to remediation.' },
  { page:'audits', target:'audit-workspace', kicker:'07 / ASSURE', title:'Validate through internal audit', text:'Run the internal audit, review samples and evidence, record findings, and send corrective work into the action plan.' },
  { page:'dashboard', target:'overview-score', kicker:'08 / COMPLETE', title:'That is the Asteria operating loop', text:'Readiness leads to control work, SoA decisions, evidence, documents, remediation, and audit assurance. You can now explore the workspace.' }
];
function openEvidenceUpdatePage(id) { state.evidenceUpdateId=id; state.page='evidence-update'; render(); window.scrollTo(0,0); }
function evidenceUpdatePage() { const item=state.evidence.find(entry=>entry.id===state.evidenceUpdateId); if(!item) return evidencePage(); const suggested=nextVersion(evidenceVersion(item)); return layout(`<div class="page-head"><div><button class="back-link" onclick="navigate('evidence')">← Back to evidence library</button><div class="eyebrow" style="margin-top:22px">Evidence lifecycle / Controlled update</div><h1>Update ${item.name}</h1><p class="subhead">Create a new evidence version without losing the previous record. Upload replacement proof and keep its control links intact.</p></div><div class="document-state-card"><span>Current version</span><strong>v${evidenceVersion(item)}</strong><small>${item.owner}</small></div></div><div class="document-update-grid"><div class="card panel"><div class="panel-head"><div><h2>New evidence version</h2><p>The suggested version adds 1 to the current version.</p></div></div><div class="version-callout"><div><span>Current</span><strong>v${evidenceVersion(item)}</strong></div><div class="version-arrow">→</div><div><span>Suggested</span><strong>v${suggested}</strong></div></div><div class="field"><label>New version number</label><input id="evidence-update-version" value="${suggested}" /><div class="field-help">Suggestion: add 1 to the current version.</div></div><div class="field"><label>Upload new evidence</label><input id="evidence-update-file" type="file" accept=".pdf,.doc,.docx,.xlsx,.csv,.png,.jpg" /><div class="field-help">Demo mode stores the filename and lifecycle metadata. The full file viewer arrives with the production repository.</div></div><div class="field"><label>What changed in this version? <span class="optional">Optional</span></label><textarea id="evidence-update-note" placeholder="Describe the new period, refreshed source, or corrected content."></textarea></div><div class="detail-grid"><div class="field"><label>Freshness</label><select id="evidence-update-fresh"><option value="fresh">Current</option><option value="expiring">Expiring soon</option><option value="expired">Expired</option></select></div><div class="field"><label>Expiry date</label><input id="evidence-update-expiry" type="date" value="${item.expiry || ''}" /></div></div><div class="modal-actions"><button class="button button-quiet" onclick="navigate('evidence')">Cancel</button><button class="button button-primary" onclick="saveEvidenceUpdate('${item.id}')">Create evidence version</button></div></div><div class="card panel"><div class="panel-head"><div><h2>Version history</h2><p>Previous evidence versions remain in the audit trail.</p></div></div><div class="version-list">${evidenceHistory(item).slice().reverse().map((entry,index)=>`<div class="version-row"><div class="version-number">v${entry.version}</div><div><strong>${index===0?'Current version':'Previous version'}</strong><p>${entry.note}</p><small>${entry.date}</small></div></div>`).join('')}</div><div class="callout" style="display:block;margin-top:20px"><h3>Control links remain attached</h3><p>This update carries forward ${item.refs.length} linked control reference${item.refs.length===1?'':'s'}.</p></div></div></div>`, 'Evidence update'); }
function saveEvidenceUpdate(id) { const item=state.evidence.find(entry=>entry.id===id); if(!item) return; const version=document.getElementById('evidence-update-version').value.trim(); if(!version) return toast('Enter a version number'); const file=document.getElementById('evidence-update-file').files[0]; const note=document.getElementById('evidence-update-note').value.trim() || 'Version updated without a change summary'; item.history=evidenceHistory(item); item.history.push({version,date:'15 Aug 2026',note}); item.version=version; item.fileName=file?.name || item.fileName || item.name; item.expiry=document.getElementById('evidence-update-expiry').value; item.freshness=document.getElementById('evidence-update-fresh').value; if(file) item.name=file.name; save(); state.page='evidence'; render(); toast(`${item.name} updated to version ${version}`); }
function openEvidenceHistory(id) { const item=state.evidence.find(entry=>entry.id===id); if(!item) return; document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Evidence / Version history</div><h2 style="margin-top:7px">${item.name}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="version-list">${evidenceHistory(item).slice().reverse().map((entry,index)=>`<div class="version-row"><div class="version-number">v${entry.version}</div><div><strong>${index===0?'Current version':'Previous version'}</strong><p>${entry.note}</p><small>${entry.date}</small></div></div>`).join('')}</div><div class="modal-actions"><button class="button button-primary" onclick="closeModal()">Close history</button></div></div></div></div>`); }
function evidencePage() { const rows=state.evidence.map(e=>`<tr><td><div class="document-name"><span class="file-icon clickable-file" onclick="openDemoDocument('${e.name}','evidence')">${e.type}</span><div><div class="control-title clickable-title" onclick="openDemoDocument('${e.name}','evidence')">${e.name}</div><div class="control-sub">v${evidenceVersion(e)} · ${e.owner} · collected ${e.date}</div></div></div></td><td>${evidenceAssignmentPicker(e)}<div class="control-sub">${e.refs.length} linked reference${e.refs.length===1?'':'s'}</div></td><td>${badge(e.freshness)}${e.expiry?`<div style="margin-top:6px">${documentExpiry(e)}</div>`:''}</td><td><div class="row-actions"><button class="table-action" onclick="openEvidenceUpdatePage(${e.id})">Update evidence</button><button class="table-action" onclick="openEvidenceHistory(${e.id})">Version history</button><button class="table-action" onclick="openDemoDocument('${e.name}','evidence')">View demo file</button><button class="table-action" onclick="removeEvidence(${e.id})">Remove</button></div></td></tr>`).join(''); const expired=state.evidence.filter(e=>e.freshness==='expired').length; const current=state.evidence.filter(e=>e.freshness==='fresh').length; const linked=state.evidence.reduce((n,e)=>n+e.refs.length,0); return layout(`<div class="page-head"><div><div class="eyebrow">Proof / Linked evidence</div><h1>Evidence library</h1><p class="subhead">A controlled register for the proof behind your ISMS. Keep ownership, freshness, and control traceability in the same place.</p></div><button class="button button-primary" onclick="openUpload()">+ Add evidence</button></div>${assignmentSelector()}<div class="evidence-metrics"><div class="card evidence-metric"><span class="eyebrow">Total evidence</span><strong>${state.evidence.length}</strong><small>Registered items</small></div><div class="card evidence-metric"><span class="eyebrow">Current</span><strong class="metric-good">${current}</strong><small>Ready for review</small></div><div class="card evidence-metric"><span class="eyebrow">Needs attention</span><strong class="metric-alert">${expired}</strong><small>Expired or expiring</small></div><div class="card evidence-metric"><span class="eyebrow">Traceability</span><strong>${linked}</strong><small>Control links</small></div></div><div class="card panel evidence-register-panel" data-tour="evidence-register"><div class="panel-head"><div><h2>Evidence register</h2><p>Search and inspect supporting material, then assign it to one or more controls.</p></div><button class="link" onclick="exportEvidenceExcel()">Export register to Excel</button></div><div style="overflow:auto"><table><thead><tr><th>Evidence item</th><th>Linked controls</th><th>Freshness</th><th>Actions</th></tr></thead><tbody>${rows || '<tr><td colspan="4" class="empty-state">No evidence has been added yet.</td></tr>'}</tbody></table></div></div><div class="evidence-insight-grid"><div class="card panel"><div class="panel-head"><div><h2>Coverage signals</h2><p>What needs attention before an auditor samples the register</p></div></div><div class="activity"><div class="activity-item"><span class="activity-dot" style="background:var(--coral);box-shadow:0 0 0 5px #fdebe6"></span><p><strong>${expired} evidence item${expired===1?'':'s'} expired or expiring</strong><br><span class="control-sub">Renew the source and create a fresh version.</span></p></div><div class="activity-item"><span class="activity-dot" style="background:var(--gold);box-shadow:0 0 0 5px #fbf1dc"></span><p><strong>${controls.filter(c=>state.statuses[c.ref]==='implemented' && !state.evidence.some(e=>e.refs.includes(c.ref))).length} implemented controls lack proof</strong><br><span class="control-sub">Assign evidence from the control catalogue.</span></p></div></div></div><div class="card panel"><div class="panel-head"><div><h2>Evidence standard</h2><p>Every item should answer three questions</p></div></div><div class="evidence-standard"><div><b>1</b><span>What is it?</span><small>Name the policy, report, export, or record.</small></div><div><b>2</b><span>Who owns it?</span><small>Assign a responsible person or team.</small></div><div><b>3</b><span>What does it prove?</span><small>Link it to the exact control and page range.</small></div></div></div></div>`, 'Evidence library'); }
function decorateLifecycleButtons() { const labels=['Update document','Version history','View demo file','Remove evidence']; document.querySelectorAll('.row-actions').forEach(row=>row.querySelectorAll('.table-action').forEach((button,index)=>{ const label=labels[index] || 'Open action'; button.title=label; button.setAttribute('aria-label',label); button.dataset.icon=index===0?'↻':index===1?'◷':index===2?'◉':'×'; })); }
function render() { const pages={dashboard:dashboard,controls:controlsPage,soa:soaPage,evidence:evidencePage,policies:()=>documentsPage('policy'),procedures:()=>documentsPage('procedure'),'document-update':documentUpdatePage,'evidence-update':evidenceUpdatePage,gaps:gapsPage,audits:auditsPage,actions:actionsPage,roadmap:roadmapPage}; document.getElementById('tour-layer')?.remove(); if(!state.authenticated) { document.getElementById('app').innerHTML=loginPage(); return; } document.getElementById('app').innerHTML=pages[state.page](); decorateLifecycleButtons(); const tourTarget={policies:'.card.panel',procedures:'.card.panel',gaps:'.card.panel',audits:'.card.panel'}[state.page]; const tourName={policies:'document-register',procedures:'document-register',gaps:'gap-register',audits:'audit-workspace'}[state.page]; if(tourTarget && tourName) document.querySelector(tourTarget)?.setAttribute('data-tour',tourName); if(!state.tourComplete) requestAnimationFrame(()=>{ renderTour(); addTourSkip(); }); }
function navigate(page) { if(!state.authenticated) return; state.page=page; state.query=''; render(); window.scrollTo(0,0); }
function renderTour() { if(state.tourComplete || !state.authenticated) return; const step=tourSteps[state.tourStep]; const target=document.querySelector(`[data-tour="${step.target}"]`); if(!target) return; document.getElementById('tour-layer')?.remove(); const rect=target.getBoundingClientRect(); const left=Math.min(Math.max(rect.left,18),window.innerWidth-rect.width-18); const top=Math.min(Math.max(rect.top,18),window.innerHeight-rect.height-18); const cardTop=rect.bottom+18 < window.innerHeight-205 ? rect.bottom+18 : Math.max(18,rect.top-190); document.body.insertAdjacentHTML('beforeend',`<div id="tour-layer" class="tour-layer"><div class="tour-spotlight" style="left:${left-7}px;top:${top-7}px;width:${rect.width+14}px;height:${rect.height+14}px"></div><section class="tour-dialog" style="left:${Math.min(Math.max(left,18),window.innerWidth-390)}px;top:${cardTop}px"><div class="tour-kicker">${step.kicker}</div><h2>${step.title}</h2><p>${step.text}</p><div class="tour-footer"><span>${state.tourStep+1} of ${tourSteps.length}</span><button id="tour-next" class="button button-primary" onclick="advanceTour()">${state.tourStep === tourSteps.length-1 ? 'Enter workspace' : 'Next'} <b>→</b></button></div><div class="tour-cooldown" id="tour-cooldown"></div></section></div>`); }
let tourCooling=false;
function advanceTour() { if(tourCooling) return; tourCooling=true; const button=document.getElementById('tour-next'); const countdown=document.getElementById('tour-cooldown'); let seconds=3; button.disabled=true; button.classList.add('cooling'); countdown.textContent=`Next available in ${seconds}s`; const timer=setInterval(()=>{ seconds-=1; if(seconds<=0) { clearInterval(timer); tourCooling=false; if(state.tourStep === tourSteps.length-1) { state.tourComplete=true; sessionStorage.setItem('asteria-tour-complete','1'); document.getElementById('tour-layer')?.remove(); toast('Walkthrough complete. Your workspace is ready.'); return; } state.tourStep+=1; state.page=tourSteps[state.tourStep].page; render(); return; } countdown.textContent=`Next available in ${seconds}s`; },1000); }
function toggleMenu() { document.getElementById('sidebar').classList.toggle('open'); }
function toast(message) { const el=document.getElementById('toast'); el.textContent=message; el.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer=setTimeout(()=>el.classList.remove('show'),2600); }
function openControl(ref) { const c=controls.find(x=>x.ref===ref); const guidance=friendlyGuidance(c); state.selectedControl=ref; const existing=state.soa[ref]?.justification || ''; document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${c.ref} / ${themes[c.theme]}</div><h2 style="margin-top:7px">${c.title}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="control-explainer"><div><label>In plain language</label><p>${guidance.intent}</p></div><div><label>Typical proof</label><p>${guidance.evidence}</p></div></div><p class="subhead" style="margin:20px 0 22px">${c.description}</p><div class="field"><label>Implementation status</label><select id="modal-status"><option value="implemented" ${state.statuses[ref]==='implemented'?'selected':''}>Implemented</option><option value="partial" ${state.statuses[ref]==='partial'?'selected':''}>Partial</option><option value="open" ${state.statuses[ref]==='open'?'selected':''}>Not started</option><option value="na" ${state.statuses[ref]==='na'?'selected':''}>Not applicable</option></select></div><div class="field"><label>Linked evidence · choose one or more</label><select id="modal-evidence" class="select evidence-modal-select" multiple size="4" onchange="renderEvidenceDetails('${ref}')">${evidenceOptions(ref)}</select><div class="field-help">Select multiple items with Ctrl/Cmd-click. Add page-level traceability below.</div></div><div id="evidence-detail-fields"></div><div class="field document-link-field"><label>Linked ISMS policies and procedures</label>${documentPicker(ref)}<div class="field-help">These controlled documents are treated as audit evidence for this exact control.</div></div><div class="field"><label>SoA rationale / implementation note</label><textarea id="modal-note" placeholder="Explain why this control is included or excluded, and what is currently in place.">${existing}</textarea></div><div class="modal-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveControl('${ref}')">Save control</button></div></div></div></div>`); requestAnimationFrame(()=>renderEvidenceDetails(ref)); }
function renderEvidenceDetails(ref) { const select=document.getElementById('modal-evidence'); const holder=document.getElementById('evidence-detail-fields'); if(!select || !holder) return; const ids=Array.from(select.selectedOptions).map(option=>Number(option.value)); holder.innerHTML=ids.map(id=>{ const evidence=state.evidence.find(item=>item.id===id); const detail=state.evidenceDetails[evidenceKey(ref,id)] || {}; return `<div class="evidence-detail"><div class="evidence-detail-head"><strong>${evidence.name}</strong><span>${evidence.type} · ${evidence.owner}</span></div><div class="detail-grid"><div class="field"><label>From page</label><input id="from-${ref}-${id}" value="${detail.fromPage || ''}" placeholder="e.g. 12" inputmode="numeric" /></div><div class="field"><label>To page</label><input id="to-${ref}-${id}" value="${detail.toPage || ''}" placeholder="e.g. 16" inputmode="numeric" /></div></div><div class="field"><label>Why does this evidence match this control? <span class="optional">Optional</span></label><textarea id="why-${ref}-${id}" placeholder="Add a short traceability note.">${detail.justification || ''}</textarea></div></div>`; }).join('') || '<div class="field-help evidence-empty">Choose evidence above to add page ranges and a traceability note.</div>'; }
function saveControl(ref) { const status=document.getElementById('modal-status').value; const note=document.getElementById('modal-note').value.trim(); const selected=Array.from(document.getElementById('modal-evidence').selectedOptions).map(option=>Number(option.value)); state.evidence.forEach(e=>{ e.refs=e.refs.filter(linkedRef=>linkedRef!==ref); if(selected.includes(e.id)) e.refs.push(ref); }); selected.forEach(id=>{ const fromPage=document.getElementById(`from-${ref}-${id}`)?.value.trim() || ''; const toPage=document.getElementById(`to-${ref}-${id}`)?.value.trim() || ''; const justification=document.getElementById(`why-${ref}-${id}`)?.value.trim() || ''; state.evidenceDetails[evidenceKey(ref,id)]={fromPage,toPage,justification}; }); state.statuses[ref]=status; state.soa[ref].applicable=status!=='na'; state.soa[ref].justification=note; save(); closeModal(); render(); toast(`${ref} updated with ${selected.length} linked evidence item${selected.length === 1 ? '' : 's'}`); }
function setStatus(ref,value) { state.statuses[ref]=value; state.soa[ref].applicable=value!=='na'; save(); render(); }
function setApplicable(ref,value) { state.soa[ref].applicable=value; if(value && state.statuses[ref]==='na') state.statuses[ref]='open'; save(); render(); }
function closeModal() { document.getElementById('modal')?.remove(); }
function openUpload(ref = '') { document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Evidence register / New item</div><h2 style="margin-top:7px">Add supporting evidence</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="field"><label>File or evidence name</label><input id="ev-file" type="file" accept=".pdf,.csv,.xlsx,.doc,.docx,.png,.jpg" /><input id="ev-name" style="margin-top:8px" placeholder="Or enter a name manually" /></div><div class="field"><label>Owner</label><input id="ev-owner" value="Mariam Al-Hadi" /></div><div class="field"><label>Linked control references</label><input id="ev-refs" value="${ref}" placeholder="e.g. A.5.15, A.8.2" /></div><div class="field"><label>Freshness</label><select id="ev-fresh"><option value="fresh">Current</option><option value="expiring">Expiring soon</option><option value="expired">Expired</option></select></div><div class="modal-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveEvidence()">Add evidence</button></div></div></div></div>`); }
function saveEvidence() { const file=document.getElementById('ev-file').files[0]; const name=document.getElementById('ev-name').value.trim() || file?.name; if(!name) return toast('Choose a file or give the evidence a name first'); state.evidence.unshift({id:Date.now(),name,type:name.split('.').pop().slice(0,3).toUpperCase()||'DOC',owner:document.getElementById('ev-owner').value.trim()||'Unassigned',date:'15 Aug 2026',freshness:document.getElementById('ev-fresh').value,refs:document.getElementById('ev-refs').value.split(',').map(x=>x.trim()).filter(x=>controls.some(c=>c.ref===x) || state.gaps.some(g=>g.id===x))}); save(); closeModal(); render(); toast('Evidence added to the register'); }
function removeEvidence(id) { state.evidence=state.evidence.filter(e=>e.id!==id); save(); render(); toast('Evidence removed'); }
function exportSoA() { const rows=controls.map(c=>`<tr><td>${c.ref}</td><td>${c.title}</td><td>${state.soa[c.ref]?.applicable?'Applicable':'Not applicable'}</td><td>${statusLabel(state.statuses[c.ref])}</td><td>${state.soa[c.ref]?.justification || '—'}</td></tr>`).join(''); const printWindow=window.open('', '_blank'); if(!printWindow) return toast('Allow pop-ups to print the SoA'); printWindow.document.write(`<html><head><title>Asteria SoA — Noor FinTech</title><style>body{font:12px Arial;color:#202a36;padding:30px}h1{font:24px Georgia;color:#172735}p{color:#77808b}table{border-collapse:collapse;width:100%;margin-top:24px}th,td{text-align:left;padding:8px;border-bottom:1px solid #ddd;vertical-align:top}th{font-size:10px;text-transform:uppercase;color:#77808b}</style></head><body><h1>Statement of Applicability</h1><p>Noor FinTech · ISO 27001:2022 · Generated 15 August 2026</p><table><thead><tr><th>Reference</th><th>Control</th><th>Applicability</th><th>Status</th><th>Rationale</th></tr></thead><tbody>${rows}</tbody></table></body></html>`); printWindow.document.close(); printWindow.focus(); setTimeout(()=>printWindow.print(),250); toast('Print view opened — choose Save as PDF'); }
function addTourSkip() { const footer=document.querySelector('.tour-footer'); if(!footer || document.getElementById('tour-skip')) return; const skip=document.createElement('button'); skip.id='tour-skip'; skip.className='tour-skip'; skip.type='button'; skip.textContent='Skip walkthrough'; skip.onclick=skipTour; footer.insertBefore(skip,footer.firstChild); document.getElementById('tour-cooldown')?.remove(); }
function skipTour() { state.tourComplete=true; sessionStorage.setItem('asteria-tour-complete','1'); document.getElementById('tour-layer')?.remove(); toast('Walkthrough skipped. Your workspace is ready.'); }
function advanceTour() { if(state.tourStep === tourSteps.length-1) { state.tourComplete=true; sessionStorage.setItem('asteria-tour-complete','1'); document.getElementById('tour-layer')?.remove(); toast('Walkthrough complete. Your workspace is ready.'); return; } state.tourStep+=1; state.page=tourSteps[state.tourStep].page; render(); }
render();
loadCRFControls();
